var t=`0585-fitchi`;var o=`world-0585`;var i=`TM`;var a=`central-asia`;var r=8;var l=78;var g={en:`Fitchi`,ua:`Фітчі`};var s={en:`A traditional dish from Turkmenistan, centered on all-purpose flour, ground beef, yellow onion, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туркменістан. Основні складники: пшеничне борошно універсальне, яловичий фарш, жовта цибуля, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,430,`g`],[`water`,200,`ml`],[`unsalted-butter`,80,`g`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-beef`,540,`g`],[`yellow-onion`,220,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:16,i:[]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[[`chicken-egg`,1,`pcs`]]}];var d={slug:t,id:o,country:`TM`,region:a,servings:8,minutes:78,title:g,text:s,steps:u};export{i as country,d as default,o as id,l as minutes,a as region,r as servings,t as slug,u as steps,s as text,g as title};